181			} else if (Pattern.matches("^(\\/api\\/clients\\/[0-9]+\\/apn).*", requestURI)) {
182				serviceClass = "S07";
183			} else if (Pattern.matches("^(\\/api\\/clients\\/[0-9]+\\/terms).*", requestURI)) {
