		session.setAttribute("deviceInfo", CommonUtil.nvl(req.getHeader("deviceInfo")));
		session.setAttribute("isSelfSufficientModel", CommonUtil.nvl(req.getHeader("isSelfSufficientModel")));

		logger.info("[ LOCALE ] " + req.getHeader("lang"));
		String localeStr = Constants.LOCALE_KOREAN;
		if (!CommonUtil.isNull(req.getHeader("lang"))) {
			localeStr = (String) req.getHeader("lang");
			if (!localeStr.equals(Constants.LOCALE_ENGLISH) 
					&& !localeStr.equals(Constants.LOCALE_CHINESE) 
					&& !localeStr.equals(Constants.LOCALE_VIETNAMESE)) {
				localeStr = Constants.LOCALE_KOREAN;
			}
		}
		Locale locale = new Locale(localeStr);
		localeResolver.setLocale(req, res, locale);
		session.setAttribute("lang", locale);

		if (uri.indexOf("/seq") > -1) {

		} else {

			LogInfo logInfo = new LogInfo(
					"SVC"
					,CommonUtil.nvl(req.getRemoteAddr())
					, (String)session.getAttribute("deviceInfo")
					, CommonUtil.nvl(req.getHeader("osInfo"))
					, (String)session.getAttribute("networkInfo")
					, ""
					, CommonUtil.nvl(req.getHeader("deviceModel"))
					, "1"
					, ""	// MEMBER_ID
					, ""
					, ""
					, ""
					, ""
					, ""
					, "");
			String[] uriArray = uri.split("/");
			String clientSeq = uriArray[ uriArray.length - 2 ];
			if (!clientSeq.matches("^[0-9]+$")) {
				logInfo = getServiceCode(req.getRequestURI(), logInfo);
				logInfo.setRESULT_CODE(Constants.API_ERR_INVALID_CLIENT_SEQ);
				lgLogger.info(logInfo.toString());
				res.sendRedirect("/api/clients/error/" + Constants.API_ERR_INVALID_CLIENT_SEQ);
				return false;
			}

			session.setAttribute("clientSeq", Long.valueOf(clientSeq));

			ParamMap param = new ParamMap(req);
			param.put("clientSeq", clientSeq);

			ResultMap clientInfo = apiService.getClientNameAndTemplate(param);
			String sqlSessionTemplate = clientInfo.getString("sqlSessionTemplate");
			session.setAttribute("clientName", CommonUtil.nvl(clientInfo.getString("fullClientName")));

			logInfo.setCLIENT_ID(CommonUtil.clientIdFormat(Long.parseLong(clientSeq)));
			logInfo.setCLIENT_NAME(CommonUtil.nvl(clientInfo.getString("fullClientName")));

			if (!CommonUtil.isNull(sqlSessionTemplate)) {
				session.setAttribute(Constants.SQL_SESSION_TEMPLATE_NAME, sqlSessionTemplate + "SqlSessionTemplate");
				session.setAttribute(Constants.SQL_TRANSACTION_MANAGER_NAME, sqlSessionTemplate + "TransactionManager");
			}

			if (uri.indexOf("/auth") == -1) {

				//실패용 통합 로그 생성생성
				if (CommonUtil.isNull(req.getHeader("token"))) {
					//통합 로그 출력
					logInfo = getServiceCode(req.getRequestURI(), logInfo);
					logInfo.setRESULT_CODE(Constants.MISSING_TOKEN_VALUE_CODE);
					lgLogger.info(logInfo.toString());
					res.sendRedirect("/api/clients/error/" + Constants.MISSING_TOKEN_VALUE_CODE);
					return false;
				}
				param.put("token", req.getHeader("token"));

				ResultMap checkToken = apiService.checkToken(param);
				if (CommonUtil.isNull(checkToken)) {
					//통합 로그 출력
					logInfo = getServiceCode(req.getRequestURI(), logInfo);
					logInfo.setRESULT_CODE(Constants.INVALID_TOKEN_CODE);
					lgLogger.info(logInfo.toString());
					res.sendRedirect("/api/clients/error/" + Constants.INVALID_TOKEN_CODE);
					return false;
				} else if (checkToken.strToBoolean(checkToken.getString("isExpiredToken"))) {
					//통합 로그 출력
					logInfo = getServiceCode(req.getRequestURI(), logInfo);
					logInfo.setRESULT_CODE(Constants.TOKEN_EXPIRED_CODE);
					lgLogger.info(logInfo.toString());
					res.sendRedirect("/api/clients/error/" + Constants.TOKEN_EXPIRED_CODE);
					return false;
				}
				long memberSeq = checkToken.getLong("memberSeq");
				logInfo.setMEMBER_ID(CommonUtil.memberIdFormat(memberSeq));
				session.setAttribute("memberSeq", memberSeq);
				session.setAttribute("ctn", securityModule.AES256_Decrypt(checkToken.getString("ctn")).trim());
				session.setAttribute("exceptionPolicy", checkToken.getString("exceptionPolicy"));
				String ctn = securityModule.AES256_Decrypt(checkToken.getString("ctn"));
				if (ctn != null && !ctn.equals("false")) {
					session.setAttribute("ctn", ctn);
				}
			}

		}

		return true;
	}

	private LogInfo getServiceCode(String requestURI, LogInfo logInfo) {
		String serviceClass = "";
		String legacyClass = "";
		if (Pattern.matches("^(\\/api\\/clients\\/seq).*", requestURI)) {
			serviceClass = "S01";
		} else if (Pattern.matches("^(\\/api\\/clients\\/[0-9]+\\/auth).*", requestURI)) {
			serviceClass = "S02";
			legacyClass = "K07";
		} else if (Pattern.matches("^(\\/api\\/clients\\/[0-9]+\\/solutions).*", requestURI)) {
			serviceClass = "S03";
		} else if (Pattern.matches("^(\\/api\\/clients\\/[0-9]+\\/location).*", requestURI)) {
			serviceClass = "S04";
		} else if (Pattern.matches("^(\\/api\\/clients\\/[0-9]+\\/leave).*", requestURI)) {
			serviceClass = "S05";
		} else if (Pattern.matches("^(\\/api\\/clients\\/[0-9]+\\/plants).*", requestURI)) {
			serviceClass = "S06";
		} else if (Pattern.matches("^(\\/api\\/clients\\/[0-9]+\\/apn).*", requestURI)) {
			serviceClass = "S07";
		} else if (Pattern.matches("^(\\/api\\/clients\\/[0-9]+\\/terms).*", requestURI)) {
			serviceClass = "S08";
		} else if (Pattern.matches("^(\\/mobile\\/clients\\/[0-9]+).*", requestURI)) {
			serviceClass = "S09";
		} else if (Pattern.matches("^(\\/api\\/clients\\/[0-9]+\\/notice).*", requestURI)) {
			serviceClass = "S10";
		} else if (Pattern.matches("^(\\/api\\/clients\\/[0-9]+\\/interlockingapp).*", requestURI)) {
			serviceClass = "S11";
		} else if (Pattern.matches("^(\\/api\\/clients\\/[0-9]+\\/qualitydata).*", requestURI)) {
			serviceClass = "S12";
		}

		logInfo.setSVC_CLASS(serviceClass);
		logInfo.setLEGACY_CLASS(legacyClass);

		return logInfo;
	}

	@Override
	public void postHandle(HttpServletRequest req, HttpServletResponse res, Object handler, ModelAndView mnv) throws Exception {
		logger.info("[LoginInterceptor] postHandle");
	}

	@Override
	public void afterCompletion(HttpServletRequest req, HttpServletResponse res, Object handler, Exception e) throws Exception {
		logger.info("[LoginInterceptor] afterCompletion");
	}


