150		private int compareVersion(String v1, String v2) {
151			String[] parts1 = v1.split("\\.");
152			String[] parts2 = v2.split("\\.");
153			for (int i = 0; i < parts1.length; i++) {
154				int diff = Integer.parseInt(parts1[i]) - Integer.parseInt(parts2[i]);
155				if (diff != 0) return diff;
156			}
157			return 0;
158		}
