161		public ClientResultMap initClient(ParamMap param, HttpServletRequest request) throws LogicException {
162			ClientResultMap result = new ClientResultMap();
163			int loggerStep = 0;
164	
165			try {
166																	
167				logger.info("[STEP{}] - Validate CTN", ++loggerStep);
168				String ctn = param.getString("ctn");
169				if (ctn == null || ctn.isEmpty()) {
170					throw new LogicException(Constants.CTN_IS_REQUIRED_MSG, Constants.CTN_IS_REQUIRED_CODE);
171				}
172	
173				logger.info("[STEP{}] - Get member info by CTN", ++loggerStep);
174				String ctnHash = hashUtil.hmacSha256(ctn);
175				param.put("ctnHash", ctnHash);
176				Map<String, Object> member = dao.getMemberByCtn(param);
177				if (member == null) {
178					throw new LogicException(Constants.NOT_JOINED_MEMBER_MSG, Constants.NOT_JOINED_MEMBER_CODE);
179				}
180	
181				long memberSeq = ((Number) member.get("memberSeq")).longValue();
182				long clientSeq = ((Number) member.get("clientSeq")).longValue();
183				String knoxKey = (String) member.get("knoxKey");
184				String salt = (String) member.get("salt");
185	
186				logger.info("[STEP{}] - Resolve salt", ++loggerStep);
187				if (salt == null || salt.isEmpty()) {
188					byte[] saltBytes = new byte[32];
189					SECURE_RANDOM.nextBytes(saltBytes);
190					salt = CommonUtil.byteToHexString(saltBytes);
191					ParamMap saltParam = new ParamMap();
192					saltParam.put("memberSeq", memberSeq);
193					saltParam.put("salt", salt);
194					dao.updateSalt(saltParam);
195				}
196	
197				logger.info("[STEP{}] - Generate tokens", ++loggerStep);
198				LocalDateTime now = LocalDateTime.now();
199				DateTimeFormatter fmt = DateTimeFormatter.ofPattern("yyyyMMddHHmmss");
200				String issuedAt = now.format(fmt);
201				String accessExpiredAt = now.plusHours(24).format(fmt);
202				String refreshExpiredAt = now.plusMonths(6).format(fmt);
203	
204				ObjectMapper objectMapper = new ObjectMapper();
205	
206				Map<String, Object> accessTokenMap = new HashMap<>();
207				accessTokenMap.put("memberSeq", memberSeq);
208				accessTokenMap.put("clientSeq", clientSeq);
209				accessTokenMap.put("issuedAt", issuedAt);
210				accessTokenMap.put("expiredAt", accessExpiredAt);
211				accessTokenMap.put("tokenType", "ACCESS");
212				String accessTokenPlain = objectMapper.writeValueAsString(accessTokenMap);
213	
214				Map<String, Object> refreshTokenMap = new HashMap<>();
215				refreshTokenMap.put("memberSeq", memberSeq);
216				refreshTokenMap.put("clientSeq", clientSeq);
217				refreshTokenMap.put("issuedAt", issuedAt);
218				refreshTokenMap.put("expiredAt", refreshExpiredAt);
219				refreshTokenMap.put("tokenType", "REFRESH");
220				String refreshTokenPlain = objectMapper.writeValueAsString(refreshTokenMap);
221	
222				logger.info("[STEP{}] - Encrypt tokens with KMS CMK4", ++loggerStep);
223				String accessToken = tokenEncryptionService.encrypt(accessTokenPlain);
224				String refreshToken = tokenEncryptionService.encrypt(refreshTokenPlain);
225	
226				logger.info("[STEP{}] - Save refresh token hash to DB", ++loggerStep);
227				String refreshTokenHash = passwordEncoder.encode(refreshToken);
228				ParamMap tokenParam = new ParamMap();
229				tokenParam.put("memberSeq", memberSeq);
230				tokenParam.put("refreshTokenHash", refreshTokenHash);
231				dao.updateRefreshTokenHash(tokenParam);
232	
233				logger.info("[STEP{}] - Update FCM token", ++loggerStep);
234				String fcmToken = param.getString("fcmToken");
235				if (fcmToken != null && !fcmToken.isEmpty()) {
236					ParamMap fcmParam = new ParamMap();
237					fcmParam.put("memberSeq", memberSeq);
238					fcmParam.put("fcmToken", fcmToken);
239					dao.updateFcmToken(fcmParam);
240				}
241	
242				logger.info("[STEP{}] - Build response", ++loggerStep);
243				Map<String, Object> data = new HashMap<>();
244				data.put("accessToken", accessToken);
245				data.put("refreshToken", refreshToken);
246				data.put("salt", salt);
247				data.put("knoxKey", knoxKey);
248				result.setData(data);
249	
250			} catch (LogicException le) {
251				logger.error("[initClient] LogicException: code={}, message={}", le.getCode(), le.getMessage());
252				result.setCode(le.getCode());
253				result.setMessage(le.getMessage());
254			} catch (Exception e) {
255				logger.error("[initClient] Exception: {}", e.getMessage());
256				result.setCode(Constants.UNKNOWN_ERR_CODE);
257				result.setMessage(e.getMessage());
258			}
259	
260			return result;
261		}
