342		public ClientResultMap getAuth(ParamMap param) throws LogicException {
343			ClientResultMap result = new ClientResultMap();
344			int loggerStep = 0;
345	
346			long memberSeq = param.getSessionLong("memberSeq");
347			long clientSeq = param.getSessionLong("clientSeq");
348			param.put("memberSeq", memberSeq);
349			param.put("clientSeq", clientSeq);
350	
351			// 1. 고객사/가입자 정보 조회
352			logger.info("[STEP{}] - Get auth info", ++loggerStep);
353			Map<String, Object> authInfo = dao.getAuthInfo(param);
354			if (authInfo == null) {
355				throw new LogicException(Constants.NOT_JOINED_MEMBER_MSG, Constants.NOT_JOINED_MEMBER_CODE);
356			}
357	
358			// 2. 고객사 해지 상태 체크
359			logger.info("[STEP{}] - Check client cancel status", ++loggerStep);
360			if (Constants.CLIENT_CANCEL_STATUS_CANCEL.equals(authInfo.get("cancelStatus"))) {
361				throw new LogicException(Constants.NOT_JOINED_CLIENT_MSG, Constants.NOT_JOINED_CLIENT_CODE);
362			}
363	
364			// 3. 앱 버전 체크 (CLIENT.APP_VERSION 기준, 낮으면 FORCE)
365			logger.info("[STEP{}] - Check app version", ++loggerStep);
366			String installedVersion = param.getString("installedVersion");
367			String clientAppVersion = (String) authInfo.get("appVersion");
368			String updateType = Constants.UPDATE_TYPE_NONE;
369			String updateUrl = null;
370			if (!CommonUtil.isNull(clientAppVersion) && !CommonUtil.isNull(installedVersion)
371					&& compareVersion(installedVersion, clientAppVersion) < 0) {
372				updateType = Constants.UPDATE_TYPE_FORCE;
373				Map<String, Object> latestInfo = dao.getLatestAppVersion();
374				if (latestInfo != null) {
375					updateUrl = (String) latestInfo.get("updateUrl");
376				}
377			}
378	
379			// 4. 가입 상태 체크
380			logger.info("[STEP{}] - Check join status", ++loggerStep);
381			if (!"01".equals(authInfo.get("joinStatus"))) {
382				throw new LogicException(Constants.NOT_JOINED_MEMBER_MSG, Constants.NOT_JOINED_MEMBER_CODE);
383			}
384	
385			String exceptionPolicy = (String) authInfo.get("exceptionPolicy");
386			boolean wifiPolicy = Constants.ON.equals(authInfo.get("wifiPolicy"));
387			boolean tetheringPolicy = Constants.ON.equals(authInfo.get("tetheringPolicy"));
388			long policySeq = ((Number) authInfo.get("policySeq")).longValue();
389			String testUserYn = (String) authInfo.get("testUserYn");
390			boolean vipYn = Constants.EXCEPTION_POLICY_VIP.equals(exceptionPolicy);
391	
392			// 4. entryStatus 업데이트
393			logger.info("[STEP{}] - Update member OS and entry status", ++loggerStep);
394			String currentNetwork = param.getString("currentNetwork");
395			if ("PRIVATE".equals(currentNetwork)) {
396				param.put("entryStatus", Constants.ENTRY_STATUS_INNER);
397			} else {
398				param.put("entryStatus", Constants.ENTRY_STATUS_OUTTER);
399			}
400			dao.updateMemberOs(param);
401	
402			// 5. ngCAS 인증
403			logger.info("[STEP{}] - Get ngCAS Certification", ++loggerStep);
404			String iccid = param.getString("iccid");
405			String ctn = (String) param.getSessionAttribute("ctn");
406			Map<String, String> nCasAuth = new HashMap<>();
407			try {
408				nCasAuth = ncasAuth.authenticateMember(ctn);
409				logger.info("[ngCas custTypeCode] : " + nCasAuth.get("CUST_TYPE_CODE"));
410			} catch (LogicException e) {
411				throw e;
412			} catch (Exception e) {
413				throw new LogicException(Constants.INVALID_AUTH_MSG, Constants.INVALID_AUTH_CODE);
414			}
415			if (!nCasAuth.get("RESPCODE").endsWith("0000")) {
416				throw new LogicException(Constants.INVALID_AUTH_MSG, Constants.INVALID_AUTH_CODE);
417			} else if (!nCasAuth.get("USIM_ICCID_NO").equals(iccid)) {
418				throw new LogicException(Constants.INVALID_USIM_ICCID_NO_MSG, Constants.INVALID_USIM_ICCID_NO_CODE);
419			}
420	
421	
422			// 7. IMEI 검증 (usimMovementAllowed 정책 반영)
423			logger.info("[STEP{}] - Validate IMEI", ++loggerStep);
424			String dbImei = (String) authInfo.get("imei");
425			String ncasImei = nCasAuth.get("IMEI");
426			String usimMovementAllowed = (String) authInfo.get("usimMovementAllowed");
427	
428			// 6. 법인/개인 판단 (ngCAS 기준)
429			logger.info("[STEP{}] - Determine corporation status", ++loggerStep);
430			boolean isCorp = false;
431			String custTypeCode = nCasAuth.get("CUST_TYPE_CODE");
432			if (Constants.NCAS_CUST_TYPE_I.equals(custTypeCode)) {
433				param.put("corporationYn", Constants.CORPORATION_N);
434			} else {
435				param.put("corporationYn", Constants.CORPORATION_Y);
436				isCorp = true;
437			}
438	
439			String imeiHash = !CommonUtil.isNull(ncasImei) ? hashUtil.hmacSha256(ncasImei) : null;
440	
441			if (Constants.ON.equals(usimMovementAllowed)) {
442				// USIM 이동 허용: IMEI 값으로 DB 무조건 업데이트
443				param.put("imei", imeiHash);
444				dao.modifyImei(param);
445			} else {
446				// USIM 이동 비허용: 법인 가입자만 IMEI 검증
447				if (isCorp) {
448					if (CommonUtil.isNull(dbImei)) {
449						// DB에 IMEI가 없으면 저장
450						param.put("imei", imeiHash);
451						dao.modifyImei(param);
452						dbImei = imeiHash;
453					}
454					// ngCAS IMEI 해시와 DB IMEI 비교
455					if (!CommonUtil.isNull(imeiHash) && !imeiHash.equals(dbImei)) {
456						throw new LogicException(Constants.INVALID_IMEI_MSG, Constants.INVALID_IMEI_CODE);
457					}
458				}
459			}
460	
461			// 10. 테스트 유저가 아닐 경우에만 법인/개인 저장
462			logger.info("[STEP{}] - Update corporation status", ++loggerStep);
463			if ("N".equals(testUserYn)) {
464				dao.modifyCorporationYn(param);
465			}
466	
467			// 11. fixedPrivateNetwork 판단
468			logger.info("[STEP{}] - Determine fixedPrivateNetwork", ++loggerStep);
469			boolean fixedPrivateNetwork = isFixedPrivateNetwork(exceptionPolicy, policySeq, isCorp);
470	
471			// 12. 응답 구성
472			logger.info("[STEP{}] - Build response", ++loggerStep);
473			Map<String, Object> data = new HashMap<>();
474			data.put("isCorporation", isCorp);
475			data.put("fixedPrivateNetwork", fixedPrivateNetwork);
476			data.put("wifiPolicy", wifiPolicy);
477			data.put("tetheringPolicy", tetheringPolicy);
478			data.put("vipYn", vipYn);
479			data.put("updateType", updateType);
480			data.put("updateUrl", updateUrl);
481			result.setData(data);
482	
483			return result;
484		}
485	
486		/**
487		 * 전용망 고정 여부 판단
488		 * - 예외2(EXCEPTION_POLICY_2) → 무조건 고정
489		 * - 일반(EXCEPTION_POLICY_NORMAL) + 정책2 + 법인 → 고정
490		 */
491		private boolean isFixedPrivateNetwork(String exceptionPolicy, long policySeq, boolean isCorporation) {
492			if (Constants.EXCEPTION_POLICY_2.equals(exceptionPolicy)) {
493				return true;
494			}
495			if (Constants.EXCEPTION_POLICY_NORMAL.equals(exceptionPolicy) && policySeq == 2 && isCorporation) {
496				return true;
497			}
498			return false;
499		}
500	
501		public ClientResultMap getNotice(ParamMap param) {
502			ClientResultMap result = new ClientResultMap();
503			result.setData(dao.getNotice(param));
504			return result;
505		}
506		
507	}
