package com.ahope.ds.client.service;

import java.security.SecureRandom;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import jakarta.servlet.http.HttpServletRequest;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.stereotype.Service;
import org.springframework.transaction.TransactionStatus;
import org.springframework.transaction.support.DefaultTransactionDefinition;

import com.ahope.ds.client.dao.ClientAPIDAO;
import com.ahope.ds.common.aws.kms.AwsKmsEncryptionService;
import com.ahope.ds.common.bean.ClientResultMap;
import com.ahope.ds.common.bean.ParamMap;
import com.ahope.ds.common.constnats.Constants;
import com.ahope.ds.common.exception.LogicException;
import com.ahope.ds.common.util.CommonUtil;
import com.ahope.ds.common.util.KMSUtil;
import com.ahope.ds.common.web.service.CommonService;
import com.fasterxml.jackson.databind.ObjectMapper;

import org.springframework.security.crypto.password.PasswordEncoder;


@Service
public class ClientAPIService extends CommonService {

	@Autowired
	private ClientAPIDAO dao;

	@Autowired
	private KMSUtil kmsUtil;

	@Autowired
	@Qualifier("tokenEncryptionService")
	private AwsKmsEncryptionService tokenEncryptionService;

	@Autowired
	private PasswordEncoder passwordEncoder;

	@Autowired
	private com.ahope.ds.common.securityModules.HashUtil hashUtil;

	@Autowired
	private com.ahope.ds.common.ncas.NcasAuth ncasAuth;

	@Autowired
	private com.ahope.ds.web.admin.qos.service.QosService qosService;

	private static final SecureRandom SECURE_RANDOM = new SecureRandom();

	@SuppressWarnings("unchecked")
	public ClientResultMap createChecklistResult(ParamMap param) throws LogicException {
		ClientResultMap result = new ClientResultMap();
		int loggerStep = 0;

		DataSourceTransactionManager txManager = getDataSourceTransactionManager();
		TransactionStatus txStatus = txManager.getTransaction(new DefaultTransactionDefinition());

		try {
			logger.info("[STEP{}] - Validate deviceInfo", ++loggerStep);
			Map<String, Object> deviceInfo = (Map<String, Object>) param.get("deviceInfo");
			if (deviceInfo == null || deviceInfo.toString().isEmpty()) {
				throw new LogicException(Constants.DEVICE_INFO_IS_REQUIRED_MSG, Constants.DEVICE_INFO_IS_REQUIRED_CODE);
			}

			List<Map<String, Object>> results = (List<Map<String, Object>>) param.get("results");
			if (results == null || results.isEmpty()) {
				throw new LogicException(Constants.RESULTS_IS_REQUIRED_MSG, Constants.RESULTS_IS_REQUIRED_CODE);
			}

			logger.info("[STEP{}] - Insert checklist result master", ++loggerStep);
			ParamMap masterParam = new ParamMap();
			masterParam.put("manufacturer", deviceInfo.get("manufacturer"));
			masterParam.put("model", deviceInfo.get("model"));
			masterParam.put("osVersion", deviceInfo.get("osVersion"));
			masterParam.put("appVersion", deviceInfo.get("appVersion"));
			masterParam.put("uuid", deviceInfo.get("uuid"));

			dao.insertChecklistResult(masterParam);
			long checklistResultSeq = masterParam.getLong("checklistResultSeq");
			logger.info("[STEP{}] - Master inserted, checklistResultSeq: {}", ++loggerStep, checklistResultSeq);

			logger.info("[STEP{}] - Insert checklist result detail", ++loggerStep);
			for (Map<String, Object> item : results) {
				long timestamp = ((Number) item.get("testDate")).longValue();
				item.put("testDate", new java.sql.Timestamp(timestamp));
			}
			ParamMap detailParam = new ParamMap();
			detailParam.put("checklistResultSeq", checklistResultSeq);
			detailParam.put("results", results);
			dao.insertChecklistResultDetail(detailParam);
			txManager.commit(txStatus);
			logger.info("[STEP{}] - Transaction committed", ++loggerStep);
		} catch (LogicException le) {
			txManager.rollback(txStatus);
			logger.error("LogicException: code={}, message={}", le.getCode(), le.getMessage());
			result.setCode(le.getCode());
			result.setMessage(le.getMessage());
		} catch (Exception e) {
			txManager.rollback(txStatus);
			logger.error("Exception: {}", e.getMessage());
			result.setCode(Constants.UNKNOWN_ERR_CODE);
			result.setMessage(e.getMessage());
		}

		return result;
	}

	public ClientResultMap  checkAppVersion(ParamMap param) throws Exception {
		ClientResultMap result = new ClientResultMap();

		String installedVersion = param.getString("installedVersion");
		if (installedVersion == null || installedVersion.isEmpty()) {
			throw new LogicException(Constants.APP_VERSION_IS_REQUIRED_MSG, Constants.APP_VERSION_IS_REQUIRED_CODE);
		}

		Map<String, Object> latestInfo = dao.getLatestAppVersion();
		if (latestInfo == null) {
			throw new LogicException(Constants.LATEST_APP_VERSION_NOT_FOUND_MSG, Constants.LATEST_APP_VERSION_NOT_FOUND_CODE);
		}

		String latestVersion = (String) latestInfo.get("appVersion");
		String updateUrl = (String) latestInfo.get("updateUrl");

		String updateType;
		if (compareVersion(installedVersion, latestVersion) >= 0) {
			updateType = Constants.UPDATE_TYPE_NONE;
			updateUrl = null;
		} else {
			updateType = Constants.UPDATE_TYPE_OPTIONAL;
		}

		Map<String, Object> data = new java.util.HashMap<>();
		data.put("updateType", updateType);
		data.put("updateUrl", updateUrl);
		result.setData(data);

		return result;
	}

	private int compareVersion(String v1, String v2) {
		String[] parts1 = v1.split("\\.");
		String[] parts2 = v2.split("\\.");
		for (int i = 0; i < parts1.length; i++) {
			int diff = Integer.parseInt(parts1[i]) - Integer.parseInt(parts2[i]);
			if (diff != 0) return diff;
		}
		return 0;
	}


	public ClientResultMap initClient(ParamMap param, HttpServletRequest request) throws LogicException {
		ClientResultMap result = new ClientResultMap();
		int loggerStep = 0;

		try {

			logger.info("[STEP{}] - Validate CTN", ++loggerStep);
			String ctn = param.getString("ctn");
			if (ctn == null || ctn.isEmpty()) {
				throw new LogicException(Constants.CTN_IS_REQUIRED_MSG, Constants.CTN_IS_REQUIRED_CODE);
			}

			logger.info("[STEP{}] - Get member info by CTN", ++loggerStep);
			String ctnHash = hashUtil.hmacSha256(ctn);
			param.put("ctnHash", ctnHash);
			Map<String, Object> member = dao.getMemberByCtn(param);
			if (member == null) {
				throw new LogicException(Constants.NOT_JOINED_MEMBER_MSG, Constants.NOT_JOINED_MEMBER_CODE);
			}

			long memberSeq = ((Number) member.get("memberSeq")).longValue();
			long clientSeq = ((Number) member.get("clientSeq")).longValue();
			String knoxKey = (String) member.get("knoxKey");
			String salt = (String) member.get("salt");

			logger.info("[STEP{}] - Resolve salt", ++loggerStep);
			if (salt == null || salt.isEmpty()) {
				byte[] saltBytes = new byte[32];
				SECURE_RANDOM.nextBytes(saltBytes);
				salt = CommonUtil.byteToHexString(saltBytes);
				ParamMap saltParam = new ParamMap();
				saltParam.put("memberSeq", memberSeq);
				saltParam.put("salt", salt);
				dao.updateSalt(saltParam);
			}

			logger.info("[STEP{}] - Generate tokens", ++loggerStep);
			LocalDateTime now = LocalDateTime.now();
			DateTimeFormatter fmt = DateTimeFormatter.ofPattern("yyyyMMddHHmmss");
			String issuedAt = now.format(fmt);
			String accessExpiredAt = now.plusHours(24).format(fmt);
			String refreshExpiredAt = now.plusMonths(6).format(fmt);

			ObjectMapper objectMapper = new ObjectMapper();

			Map<String, Object> accessTokenMap = new HashMap<>();
			accessTokenMap.put("memberSeq", memberSeq);
			accessTokenMap.put("clientSeq", clientSeq);
			accessTokenMap.put("issuedAt", issuedAt);
			accessTokenMap.put("expiredAt", accessExpiredAt);
			accessTokenMap.put("tokenType", "ACCESS");
			String accessTokenPlain = objectMapper.writeValueAsString(accessTokenMap);

			Map<String, Object> refreshTokenMap = new HashMap<>();
			refreshTokenMap.put("memberSeq", memberSeq);
			refreshTokenMap.put("clientSeq", clientSeq);
			refreshTokenMap.put("issuedAt", issuedAt);
			refreshTokenMap.put("expiredAt", refreshExpiredAt);
			refreshTokenMap.put("tokenType", "REFRESH");
			String refreshTokenPlain = objectMapper.writeValueAsString(refreshTokenMap);

			logger.info("[STEP{}] - Encrypt tokens with KMS CMK4", ++loggerStep);
			String accessToken = tokenEncryptionService.encrypt(accessTokenPlain);
			String refreshToken = tokenEncryptionService.encrypt(refreshTokenPlain);

			logger.info("[STEP{}] - Save refresh token hash to DB", ++loggerStep);
			String refreshTokenHash = passwordEncoder.encode(refreshToken);
			ParamMap tokenParam = new ParamMap();
			tokenParam.put("memberSeq", memberSeq);
			tokenParam.put("refreshTokenHash", refreshTokenHash);
			dao.updateRefreshTokenHash(tokenParam);

			logger.info("[STEP{}] - Update FCM token", ++loggerStep);
			String fcmToken = param.getString("fcmToken");
			if (fcmToken != null && !fcmToken.isEmpty()) {
				ParamMap fcmParam = new ParamMap();
				fcmParam.put("memberSeq", memberSeq);
				fcmParam.put("fcmToken", fcmToken);
				dao.updateFcmToken(fcmParam);
			}

			logger.info("[STEP{}] - Build response", ++loggerStep);
			Map<String, Object> data = new HashMap<>();
			data.put("accessToken", accessToken);
			data.put("refreshToken", refreshToken);
			data.put("salt", salt);
			data.put("knoxKey", knoxKey);
			result.setData(data);

		} catch (LogicException le) {
			logger.error("[initClient] LogicException: code={}, message={}", le.getCode(), le.getMessage());
			result.setCode(le.getCode());
			result.setMessage(le.getMessage());
		} catch (Exception e) {
			logger.error("[initClient] Exception: {}", e.getMessage());
			result.setCode(Constants.UNKNOWN_ERR_CODE);
			result.setMessage(e.getMessage());
		}

		return result;
	}

	public ClientResultMap sync(ParamMap param, HttpServletRequest request) {
		ClientResultMap result = new ClientResultMap();
		int loggerStep = 0;

		try {
			long memberSeq = (long) request.getSession().getAttribute("memberSeq");
			long clientSeq = (long) request.getSession().getAttribute("clientSeq");
			param.put("memberSeq", memberSeq);
			param.put("clientSeq", clientSeq);

			logger.info("[STEP{}] - Start sync", ++loggerStep);
			Map<String, Object> data = new java.util.HashMap<>();

			// 최신 약관 버전
			logger.info("[STEP{}] - Get latest terms version", ++loggerStep);
			Map<String, Object> termsVersion = dao.getLatestTermsVersion();
			data.put("latestTermsVersion", termsVersion != null ? termsVersion.get("latestTermsVersion") : null);

			// 최신 공지 버전
			logger.info("[STEP{}] - Get latest notice version", ++loggerStep);
			Map<String, Object> noticeVersion = dao.getLatestNoticeVersion();
			data.put("latestNoticeVersion", noticeVersion != null ? noticeVersion.get("latestNoticeVersion") : null);

			// 고객사 기본 정보 (배경이미지 + 연동앱 버전)
			logger.info("[STEP{}] - Get client sync info", ++loggerStep);
			Map<String, Object> clientSyncInfo = dao.getClientSyncInfo(param);
			data.put("mainBackgroundImageUrl", clientSyncInfo != null ? clientSyncInfo.get("mainBackgroundImageUrl") : null);
			data.put("interlockingAppVersion", clientSyncInfo != null ? clientSyncInfo.get("interlockingAppVersion") : null);

			// 연동앱 목록
			logger.info("[STEP{}] - Get interlocking app list", ++loggerStep);
			data.put("interlockingAppList", dao.getInterlockingAppList(param));

			// 허용 ECGI 목록 (복호화)
			logger.info("[STEP{}] - Get allowed ECGI list and decrypt", ++loggerStep);
			List<String> encryptedEcgiList = dao.getAllowedEcgiList(param);
			List<String> decryptedEcgiList = kmsUtil.simpleDataCryptoList(encryptedEcgiList, false);
			data.put("allowedEcgiList", decryptedEcgiList);
			logger.info("[STEP{}] - Decrypted ECGI list size: {}", ++loggerStep, decryptedEcgiList != null ? decryptedEcgiList.size() : 0);

			// 솔루션 목록
			logger.info("[STEP{}] - Get solution list", ++loggerStep);
			List<HashMap<String, Object>> solutionList = dao.getSolutionList(param);
			solutionList.forEach(s -> s.put("enabled", Integer.valueOf(1).equals(s.get("enabled"))));
			data.put("solutionList", solutionList);
			logger.info("[STEP{}] - Solution list size: {}", ++loggerStep, solutionList.size());

			result.setData(data);
			logger.info("[STEP{}] - Sync completed successfully", ++loggerStep);
		} catch (LogicException le) {
			logger.error("[sync] LogicException: code={}, message={}", le.getCode(), le.getMessage());
			result.setCode(le.getCode());
			result.setMessage(le.getMessage());
		} catch (Exception e) {
			logger.error("[sync] Exception: {}", e.getMessage());
			result.setCode(Constants.UNKNOWN_ERR_CODE);
			result.setMessage(e.getMessage());
		}

		return result;
	}

	public ClientResultMap getTerms() {
		ClientResultMap result = new ClientResultMap();
		Map<String, Object> terms = dao.getTerms();
		if (terms != null) {
			terms.computeIfPresent("collectingPurpose", (k, v) -> CommonUtil.restoreHtmlCodeToNormalText((String) v));
			terms.computeIfPresent("collectingItems", (k, v) -> CommonUtil.restoreHtmlCodeToNormalText((String) v));
		}
		result.setData(terms);
		return result;
	}


	/**
	 * 가입자 인증
	 * 요청: iccid, currentNetwork (PRIVATE/PUBLIC), ecgi
	 * 응답: isCorporation, fixedPrivateNetwork, wifiPolicy, tetheringPolicy, vipYn
	 */
	public ClientResultMap getAuth(ParamMap param) throws LogicException {
		ClientResultMap result = new ClientResultMap();
		int loggerStep = 0;

		long memberSeq = param.getSessionLong("memberSeq");
		long clientSeq = param.getSessionLong("clientSeq");
		param.put("memberSeq", memberSeq);
		param.put("clientSeq", clientSeq);

		// 1. 고객사/가입자 정보 조회
		logger.info("[STEP{}] - Get auth info", ++loggerStep);
		Map<String, Object> authInfo = dao.getAuthInfo(param);
		if (authInfo == null) {
			throw new LogicException(Constants.NOT_JOINED_MEMBER_MSG, Constants.NOT_JOINED_MEMBER_CODE);
		}

		// 2. 고객사 해지 상태 체크
		logger.info("[STEP{}] - Check client cancel status", ++loggerStep);
		if (Constants.CLIENT_CANCEL_STATUS_CANCEL.equals(authInfo.get("cancelStatus"))) {
			throw new LogicException(Constants.NOT_JOINED_CLIENT_MSG, Constants.NOT_JOINED_CLIENT_CODE);
		}

		// 3. 앱 버전 체크 (CLIENT.APP_VERSION 기준, 낮으면 FORCE)
		logger.info("[STEP{}] - Check app version", ++loggerStep);
		String installedVersion = param.getString("installedVersion");
		String clientAppVersion = (String) authInfo.get("appVersion");
		String updateType = Constants.UPDATE_TYPE_NONE;
		String updateUrl = null;
		if (!CommonUtil.isNull(clientAppVersion) && !CommonUtil.isNull(installedVersion)
				&& compareVersion(installedVersion, clientAppVersion) < 0) {
			updateType = Constants.UPDATE_TYPE_FORCE;
			Map<String, Object> latestInfo = dao.getLatestAppVersion();
			if (latestInfo != null) {
				updateUrl = (String) latestInfo.get("updateUrl");
			}
		}

		// 4. 가입 상태 체크
		logger.info("[STEP{}] - Check join status", ++loggerStep);
		if (!"01".equals(authInfo.get("joinStatus"))) {
			throw new LogicException(Constants.NOT_JOINED_MEMBER_MSG, Constants.NOT_JOINED_MEMBER_CODE);
		}

		String exceptionPolicy = (String) authInfo.get("exceptionPolicy");
		boolean wifiPolicy = Constants.ON.equals(authInfo.get("wifiPolicy"));
		boolean tetheringPolicy = Constants.ON.equals(authInfo.get("tetheringPolicy"));
		long policySeq = ((Number) authInfo.get("policySeq")).longValue();
		String testUserYn = (String) authInfo.get("testUserYn");
		boolean vipYn = Constants.EXCEPTION_POLICY_VIP.equals(exceptionPolicy);

		// 4. entryStatus 업데이트
		logger.info("[STEP{}] - Update member OS and entry status", ++loggerStep);
		String currentNetwork = param.getString("currentNetwork");
		if ("PRIVATE".equals(currentNetwork)) {
			param.put("entryStatus", Constants.ENTRY_STATUS_INNER);
		} else {
			param.put("entryStatus", Constants.ENTRY_STATUS_OUTTER);
		}
		dao.updateMemberOs(param);

		// 5. ngCAS 인증
		logger.info("[STEP{}] - Get ngCAS Certification", ++loggerStep);
		String iccid = param.getString("iccid");
		String ctn = (String) param.getSessionAttribute("ctn");
		Map<String, String> nCasAuth = new HashMap<>();
		try {
			nCasAuth = ncasAuth.authenticateMember(ctn);
			logger.info("[ngCas custTypeCode] : " + nCasAuth.get("CUST_TYPE_CODE"));
		} catch (LogicException e) {
			throw e;
		} catch (Exception e) {
			throw new LogicException(Constants.INVALID_AUTH_MSG, Constants.INVALID_AUTH_CODE);
		}
		if (!nCasAuth.get("RESPCODE").endsWith("0000")) {
			throw new LogicException(Constants.INVALID_AUTH_MSG, Constants.INVALID_AUTH_CODE);
		} else if (!nCasAuth.get("USIM_ICCID_NO").equals(iccid)) {
			throw new LogicException(Constants.INVALID_USIM_ICCID_NO_MSG, Constants.INVALID_USIM_ICCID_NO_CODE);
		}


		// 7. IMEI 검증 (usimMovementAllowed 정책 반영)
		logger.info("[STEP{}] - Validate IMEI", ++loggerStep);
		String dbImei = (String) authInfo.get("imei");
		String ncasImei = nCasAuth.get("IMEI");
		String usimMovementAllowed = (String) authInfo.get("usimMovementAllowed");

		// 6. 법인/개인 판단 (ngCAS 기준)
		logger.info("[STEP{}] - Determine corporation status", ++loggerStep);
		boolean isCorp = false;
		String custTypeCode = nCasAuth.get("CUST_TYPE_CODE");
		if (Constants.NCAS_CUST_TYPE_I.equals(custTypeCode)) {
			param.put("corporationYn", Constants.CORPORATION_N);
		} else {
			param.put("corporationYn", Constants.CORPORATION_Y);
			isCorp = true;
		}

		String imeiHash = !CommonUtil.isNull(ncasImei) ? hashUtil.hmacSha256(ncasImei) : null;

		if (Constants.ON.equals(usimMovementAllowed)) {
			// USIM 이동 허용: IMEI 값으로 DB 무조건 업데이트
			param.put("imei", imeiHash);
			dao.modifyImei(param);
		} else {
			// USIM 이동 비허용: 법인 가입자만 IMEI 검증
			if (isCorp) {
				if (CommonUtil.isNull(dbImei)) {
					// DB에 IMEI가 없으면 저장
					param.put("imei", imeiHash);
					dao.modifyImei(param);
					dbImei = imeiHash;
				}
				// ngCAS IMEI 해시와 DB IMEI 비교
				if (!CommonUtil.isNull(imeiHash) && !imeiHash.equals(dbImei)) {
					throw new LogicException(Constants.INVALID_IMEI_MSG, Constants.INVALID_IMEI_CODE);
				}
			}
		}

		// 10. 테스트 유저가 아닐 경우에만 법인/개인 저장
		logger.info("[STEP{}] - Update corporation status", ++loggerStep);
		if ("N".equals(testUserYn)) {
			dao.modifyCorporationYn(param);
		}

		// 11. fixedPrivateNetwork 판단
		logger.info("[STEP{}] - Determine fixedPrivateNetwork", ++loggerStep);
		boolean fixedPrivateNetwork = isFixedPrivateNetwork(exceptionPolicy, policySeq, isCorp);

		// 12. 응답 구성
		logger.info("[STEP{}] - Build response", ++loggerStep);
		Map<String, Object> data = new HashMap<>();
		data.put("isCorporation", isCorp);
		data.put("fixedPrivateNetwork", fixedPrivateNetwork);
		data.put("wifiPolicy", wifiPolicy);
		data.put("tetheringPolicy", tetheringPolicy);
		data.put("vipYn", vipYn);
		data.put("updateType", updateType);
		data.put("updateUrl", updateUrl);
		result.setData(data);

		return result;
	}

	/**
	 * 전용망 고정 여부 판단
	 * - 예외2(EXCEPTION_POLICY_2) → 무조건 고정
	 * - 일반(EXCEPTION_POLICY_NORMAL) + 정책2 + 법인 → 고정
	 */
	private boolean isFixedPrivateNetwork(String exceptionPolicy, long policySeq, boolean isCorporation) {
		if (Constants.EXCEPTION_POLICY_2.equals(exceptionPolicy)) {
			return true;
		}
		if (Constants.EXCEPTION_POLICY_NORMAL.equals(exceptionPolicy) && policySeq == 2 && isCorporation) {
			return true;
		}
		return false;
	}

	public ClientResultMap getNotice(ParamMap param) {
		ClientResultMap result = new ClientResultMap();
		result.setData(dao.getNotice(param));
		return result;
	}

