package com.ahope.ds.web.superadmin.client.controller;

import java.io.IOException;
import java.io.UnsupportedEncodingException;
import java.security.InvalidAlgorithmParameterException;
import java.security.InvalidKeyException;
import java.security.NoSuchAlgorithmException;
import java.security.NoSuchProviderException;

import javax.crypto.BadPaddingException;
import javax.crypto.IllegalBlockSizeException;
import javax.crypto.NoSuchPaddingException;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.MediaType;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestMethod;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RequestPart;
import org.springframework.web.multipart.MultipartFile;

import com.ahope.ds.common.bean.ParamMap;
import com.ahope.ds.common.exception.LogicException;
import com.ahope.ds.common.extension.annotation.History;
import com.ahope.ds.common.extension.annotation.History.HistoryType;
import com.ahope.ds.common.extension.annotation.RequestParamMap;
import com.ahope.ds.common.util.CommonUtil;
import com.ahope.ds.common.web.controller.CommonController;
import com.ahope.ds.web.superadmin.client.service.ClientService;

import io.swagger.v3.oas.annotations.Operation;
import io.swagger.v3.oas.annotations.Parameter;
import io.swagger.v3.oas.annotations.Parameters;
import io.swagger.v3.oas.annotations.enums.ParameterIn;
import io.swagger.v3.oas.annotations.media.ArraySchema;
import io.swagger.v3.oas.annotations.media.Content; 
import io.swagger.v3.oas.annotations.media.ExampleObject;
import io.swagger.v3.oas.annotations.media.Schema;
import io.swagger.v3.oas.annotations.tags.Tag;
import jakarta.servlet.http.HttpServletRequest;

@Tag(name = "Client", description = "고객사 관리 API")
@Controller
@RequestMapping("/web/super/admin/clients")
public class ClientController extends CommonController {

	@Autowired
	private ClientService service;

	@Operation(summary = "고객사 목록 화면", description = "고객사 목록 화면으로 이동합니다.")
	@RequestMapping(value = "", method = RequestMethod.GET)
	public String clientListView(@RequestParamMap ParamMap param, Model model) throws InvalidKeyException, UnsupportedEncodingException, NoSuchAlgorithmException, NoSuchPaddingException, InvalidAlgorithmParameterException, IllegalBlockSizeException, BadPaddingException, NoSuchProviderException, IOException {
		if (CommonUtil.isVulnerability(new String[] {"listLength"}, param)) {
			param.remove("listLength");
		}
		param.setSessionValue("clientSeq", null);
		model.addAllAttributes(service.getClientsSummury(param));
		model.addAllAttributes(param);
		return "superadmin/client/clientList";
	}

	@Operation(summary = "고객사 목록 조회", description = "고객사 목록을 페이징하여 조회합니다.")
	@Parameters({
		@Parameter(name = "start", description = "페이지 시작 위치", example = "0", schema = @Schema(type = "integer", format = "int32")),
		@Parameter(name = "length", description = "페이지 크기", example = "10", schema = @Schema(type = "integer", format = "int32")),
		@Parameter(name = "cancelStatus", description = "해지 상태 (01:가입, 02:해지요청, 03:해지중, 04:복구요청, 05:복구중, 06:해지, 07:즉시해지요청)", example = "01", schema = @Schema(type = "string")),
		@Parameter(name = "serviceType", description = "서비스 타입 (01:LTE폐쇄형, 02:LTE개방형, 03:5G폐쇄형, 04:5G개방형)", example = "04", schema = @Schema(type = "string")),
		@Parameter(name = "searchType", description = "검색 타입 (CLIENT_NAME: 고객사, SUB_TITLE: 공장명, SMARTPHONE_APN: 고객 전용망APN(010 단말), IOT_APN: 고객 전용망APN(012 단말), MANAGER_NAME: 담당자)", example = "CLIENT_NAME", schema = @Schema(type = "string")),
		@Parameter(name = "searchValue", description = "검색어", example = "유플러스", schema = @Schema(type = "string"))
	})
	@RequestMapping(value = "/ajax", method = RequestMethod.GET)
	public String getClientList(@RequestParamMap ParamMap param, Model model) throws UnsupportedEncodingException {
		param.put("length", param.getInt("length"));
		param.put("start", param.getInt("start"));
		param.put("lang", "" + param.getSessionAttribute("lang"));
		model.addAllAttributes(service.getClientList(param));
		return JSON_VIEW;
	}

	@Operation(summary = "고객사 등록 화면", description = "고객사 등록 화면으로 이동합니다.")
	@RequestMapping(value = "/new", method = RequestMethod.GET)
	public String getCreateClientView(@RequestParamMap ParamMap param, Model model) {
		if (CommonUtil.isVulnerability(new String[] {"listLength"}, param)) {
			param.remove("listLength");
		}
		model.addAllAttributes(service.getBasicInfo());
		model.addAllAttributes(param);
		return "superadmin/client/client";
	}

	@Operation(summary = "고객사 등록", description = "새로운 고객사를 등록합니다. 로고, 담당자 정보, 동의서 등을 포함합니다.")
	@Parameters({
		@Parameter(name = "subTitles", description = "고객사 공장명", required = true, example = "{\"ko\":\"아홉\",\"en\":\"Ahope\",\"zh\":\"九\",\"vi\":\"chín\"}", schema = @Schema(type = "string")),
		@Parameter(name = "clientName", description = "고객사명", example = "테스트고객사", schema = @Schema(type = "string")),
		@Parameter(name = "smartphoneApn", description = "고객 전용망APN(010 단말)", example = "ahope010.co.kr", schema = @Schema(type = "string")),
		@Parameter(name = "iotApn", description = "고객 전용망APN(012 단말)", example = "ahope012.co.kr", required = true, schema = @Schema(type = "string")),
		@Parameter(name = "chargeNo", description = "청구번호", example = "1234", required = true, schema = @Schema(type = "string")),
		@Parameter(name = "joinSoc", description = "부가 서비스 코드", example = "AHP0000212", required = true, schema = @Schema(type = "string")),
		@Parameter(name = "qosControlId", description = "QoS 제어 ID", example = "QOS001", required = true, schema = @Schema(type = "string")),
		@Parameter(name = "policySeq", description = "정책선택 (1: 정책1, 2: 정책2)", example = "1", required = true, schema = @Schema(type = "integer", format = "int64")),
		@Parameter(name = "internetBlockOnOff", description = "인터넷차단 부가서비스 ON/OFF (01: ON, 02: OFF)", example = "01", required = true, schema = @Schema(type = "string")),
		@Parameter(name = "smsUsage", description = "데이터 사용량 SMS발송 ON/OFF (01: ON, 02: OFF)", example = "01", required = true, schema = @Schema(type = "string")),
		@Parameter(name = "usageSmsRatio", description = "데이터 사용량 SMS 발송 비율", example = "70", required = true, schema = @Schema(type = "string")),
		@Parameter(name = "smsOnOff", description = "데이터 제어 SMS발송 ON/OFF (01: ON, 02: OFF)", example = "01", required = true, schema = @Schema(type = "string")),
		@Parameter(name = "smsJoinCancel", description = "가입/해지 SMS발송 ON/OFF (01: ON, 02: OFF)", example = "01", required = true, schema = @Schema(type = "string")),
		@Parameter(name = "autoQosControlId", description = "고객사별 자동 QoS 속도 설정 (8: 1Kbps, 9: 3Kbps)", example = "8", required = true, schema = @Schema(type = "string")),
		@Parameter(name = "manualQosControlId", description = "고객사별 수동 QoS 속도 설정 (8: 1Kbps, 9: 3Kbps)", example = "9", required = true, schema = @Schema(type = "string")),
		@Parameter(name = "cpUsimMovementAllowed", description = "C/P 기반 USIM 이동 허용 여부 (01: 허용, 02: 미허용)", example = "01", required = true, schema = @Schema(type = "string")),
		@Parameter(name = "cpZoneInOutOnOff", description = "C/P 기반 ZONE IN/OUT (01: ON, 02: OFF)", example = "02", required = true, schema = @Schema(type = "string")),
		@Parameter(name = "lbspZoneInOutOnOff", description = "LBSP 기반 ZONE IN/OUT (01: ON, 02: OFF)", example = "02", required = true, schema = @Schema(type = "string")),
		@Parameter(name = "wifiOnOff", description = "WIFI 사용 ON/OFF (01: ON, 02: OFF)", example = "02", required = true, schema = @Schema(type = "string")),
		@Parameter(name = "tetheringOnOff", description = "테더링 사용 ON/OFF (01: ON, 02: OFF)", example = "02", required = true, schema = @Schema(type = "string")),
		@Parameter(name = "oneStoreOnOff", description = "원스토어 사용 ON/OFF (01: ON, 02: OFF)", example = "01", required = true, schema = @Schema(type = "string")),
		@Parameter(name = "appStoreOnOff", description = "앱스토어 사용 ON/OFF (1: ON, 2: OFF)", example = "1", required = true, schema = @Schema(type = "string")),
		@Parameter(name = "gcmOnOff", description = "GCM ON/OFF (01: ON, 02: OFF)", example = "01", required = true, schema = @Schema(type = "string")),
		@Parameter(name = "dataCollectionOnoff", description = "데이터 수집 ON/OFF (1: ON, 2: OFF)", example = "02", required = true, schema = @Schema(type = "string")),
		@Parameter(name = "usimMovementAllowed", description = "앱 기반 USIM 이동 허용 여부", example = "02", required = true, schema = @Schema(type = "string")),
		@Parameter(name = "quotaOnOff", description = "데이터 관리 서비스 ON/OFF (01: ON, 02: OFF)", example = "02", required = true, schema = @Schema(type = "string")),
		@Parameter(name = "workingHoursOnOff", description = "근무시간 기준 차단 ON/OFF (01: ON, 02: OFF)", example = "02", required = true, schema = @Schema(type = "string")),
		@Parameter(name = "memberUsageStatsOnOff", description = "가입자별 통계 ON/OFF (01: ON, 02: OFF)", example = "02", required = true, schema = @Schema(type = "string")),
		@Parameter(name = "cpMemberUsageStatsOnOff", description = "가입자별 실시간 데이터 ON/OFF (01: ON, 02: OFF)", example = "02", required = true, schema = @Schema(type = "string")),
		@Parameter(name = "unauthorizedTrafficOnOff", description = "비인가 트래픽 현황 ON/OFF (01: ON, 02: OFF)", example = "02", required = true, schema = @Schema(type = "string")),
		@Parameter(name = "contractUsage", description = "약정 데이터량(이번 달)", example = "1", required = true, schema = @Schema(type = "integer", format = "int32")),
		@Parameter(name = "contractUsageByAdmin", description = "약정 데이터량(다음 달)", example = "33", schema = @Schema(type = "integer", format = "int32")),
		@Parameter(name = "openingInformation", description = "개통정보", schema = @Schema(type = "string")),
		@Parameter(name = "lpsMaxMemberCount", description = "LPS 등록 가능 가입자 수", example = "300", schema = @Schema(type = "integer", format = "int32")),
		@Parameter(name = "sqlSessionTemplate", description = "DB 설정 정보", schema = @Schema(type = "string")),
		@Parameter(name = "serviceType", description = "상품 종류 (04: 5G 전용망 개방형(상암), 03: 5G전용망 폐쇠형(대전), 02: LTE 전용망 개방형(상암), 01: LTE 전용망 폐쇠형(대전))", example = "04", schema = @Schema(type = "string")),
		@Parameter(name = "serviceId1", description = "U-cube 서비스 ID 1", example = "60001", schema = @Schema(type = "string")),
		@Parameter(name = "serviceId2", description = "U-cube 서비스 ID 2", example = "60002", schema = @Schema(type = "string")),
		@Parameter(name = "serviceId3", description = "U-cube 서비스 ID 3", example = "60003", schema = @Schema(type = "string")),
		@Parameter(name = "autoQosSetSms", description = "자동 QoS 설정 SMS", example = "자동 QoS 설정 SMS메시지입니다", schema = @Schema(type = "string")),
		@Parameter(name = "autoQosCancelSms", description = "자동 QoS 해지 SMS", example = "자동 QoS 해지 SMS메시지입니다", schema = @Schema(type = "string")),
		@Parameter(name = "manualQosSetSms", description = "수동 QoS 설정 SMS", example = "수동 QoS 설정 SMS메시지입니다", schema = @Schema(type = "string")),
		@Parameter(name = "manualQosCancelSms", description = "수동 QoS 해지 SMS", example = "수동 QoS 해지 SMS메시지입니다", schema = @Schema(type = "string")),
		@Parameter(name = "imeiAuthPassDevices", description = "IMEI 인증 예외 단말 모델", schema = @Schema(type = "string")),
		@Parameter(name = "incidentManagerName", description = "장애대응 담당자명", example = "홍길동", schema = @Schema(type = "string")),
		@Parameter(name = "incidentManagerPhone", description = "장애대응 담당자 연락처", example = "01012345678", schema = @Schema(type = "string")),
		@Parameter(name = "iosProfileType", description = "iOS 프로파일", schema = @Schema(type = "string")),
		@Parameter(name = "knoxEnterpriseLisenceKey", description = "Knox Enterprise 라이선스 키", schema = @Schema(type = "string")),
		@Parameter(name = "knoxLisenceKey", description = "Knox 라이선스 키", schema = @Schema(type = "string"))
	})
	@RequestMapping(value = "", method = RequestMethod.POST, consumes = MediaType.MULTIPART_FORM_DATA_VALUE)
	public String createClient(@RequestParamMap(requiredValues= {"clientName","qosControlId"}) ParamMap param
								, @Parameter(name = "clientLogo", description = "고객사 로고(Web)", required = true)
								@RequestParam ("clientLogo") MultipartFile clientLogo
								, @Parameter(name = "clientAppBkgdImg", description = "고객사 APP 배경 이미지")
								@RequestParam (value="clientAppBkgdImg", required=false) MultipartFile clientAppBkgdImg
								, @Parameter(name = "clientNameImg", description = "고객사 로고(App) 이미지")
								@RequestParam (value="clientNameImg", required=false) MultipartFile clientNameImg
								, @Parameter(name = "managerName", description = "담당자명", required = true, array = @ArraySchema(schema = @Schema(type = "string", example = "홍길동")))
								@RequestParam (value="managerName") String[] managerNames
								, @Parameter(name = "managerPhone", description = "담당자 연락처", required = true, array = @ArraySchema(schema = @Schema(type = "string", example = "01012345678")))
								@RequestParam (value="managerPhone") String[] managerPhones
								, @Parameter(name = "incidentConsentFormImg", description = "장애대응 개인정보 활용동의 파일")
								@RequestParam (value="incidentConsentFormImg", required=false) MultipartFile incidentConsentFormImg
								, @Parameter(name = "managerConsentFormImg", description = "담당자 개인정보 활용동의 파일")
								@RequestPart(value = "managerConsentFormImg", required = false) MultipartFile[] managerConsentFormImg
								, @Parameter(name = "incidentConsentFormExceptionYn", description = "장애대응 개인정보 활용동의 파일 등록 예외 여부", example = "n")
								@RequestParam (value="incidentConsentFormExceptionYn", required=false) String incidentConsentFormExceptionYn
								, @Parameter(name = "managerConsentFormExceptionYn", description = "담당자 개인정보 활용동의 파일 등록 예외 여부", array = @ArraySchema(schema = @Schema(type = "string", example = "n")))
								@RequestParam (value="managerConsentFormExceptionYn", required=false) String[] managerConsentFormExceptions
								, Model model
								, HttpServletRequest req) throws Exception {
		logger.info("[STEP 1] - Vaildation Check");

		int maxSize5MB = 1024 * 1024 * 5;
		int maxSize1MB = 1024 * 1024 * 1;

		param.put("managerNames", managerNames);
		param.put("managerPhones", managerPhones);
		param.put("managerConsentFormExceptions", managerConsentFormExceptions);
		//고객사 로고(Web)
		if (!CommonUtil.imgFileExtCheck(CommonUtil.getFileExt(clientLogo.getOriginalFilename()))) {
			throw new LogicException("VALIDATION_FAIL","003");
		}
		if (maxSize5MB < clientLogo.getSize()) {
			throw new LogicException("VALIDATION_FAIL","004");
		}
		//고객사 로고(APP)
		if (clientNameImg != null) {
			if (!CommonUtil.imgFileExtCheck(CommonUtil.getFileExt(clientNameImg.getOriginalFilename()))) {
				throw new LogicException("VALIDATION_FAIL","003");
			}
			if (maxSize1MB < clientNameImg.getSize()) {
				throw new LogicException("VALIDATION_FAIL","004");
			}
		}
		if (clientAppBkgdImg != null) {
			//고객사 APP 배경
			if (!CommonUtil.imgFileExtCheck(CommonUtil.getFileExt(clientAppBkgdImg.getOriginalFilename()))) {
				throw new LogicException("VALIDATION_FAIL","003");
			}
			if (maxSize1MB < clientAppBkgdImg.getSize()) {
				throw new LogicException("VALIDATION_FAIL","004");
			}
		}


		//장애대응담당자 개인정보활용동의서
		if (incidentConsentFormImg != null) {
			if (!CommonUtil.imgFileExtCheck(CommonUtil.getFileExt(incidentConsentFormImg.getOriginalFilename()))) {
				throw new LogicException("VALIDATION_FAIL","003");
			}
			if (maxSize5MB < incidentConsentFormImg.getSize()) {
				throw new LogicException("VALIDATION_FAIL","004");
			}
		} else {
			String incidentManagerName = param.getString("incidentManagerName");
			if (incidentConsentFormExceptionYn == null || "n".equals(incidentConsentFormExceptionYn)) {
				if (incidentManagerName != null && !"".equals(incidentManagerName)) {
					throw new LogicException("VALIDATION_FAIL", "251");
				}
			}
		}

		if (managerConsentFormImg != null) {
			//담당자 개인정보활용동의서
			int index = 0;
			for (MultipartFile managerConsentFormImgInfo : managerConsentFormImg) {
				if (managerConsentFormImgInfo.isEmpty()) {
					if (managerConsentFormExceptions[index].isEmpty() || "n".equals(managerConsentFormExceptions[index])) {
						throw new LogicException("VALIDATION_FAIL", "251");
					}
					index++;
					continue;
				}

				if (managerConsentFormImgInfo != null) {
					if (!CommonUtil.imgFileExtCheck(CommonUtil.getFileExt(managerConsentFormImgInfo.getOriginalFilename()))) {
						throw new LogicException("VALIDATION_FAIL","003");
					}
					if (maxSize5MB < managerConsentFormImgInfo.getSize()) {
						throw new LogicException("VALIDATION_FAIL","004");
					}
				}
				index++;
			}			
		}

		if (CommonUtil.isVulnerability(new String[] {"clientName", "sqlSessionTemplate", "managerName", "smartphoneApn", "iotApn", "subTitles"
				, "knoxEnterpriseLisenceKey", "knoxLisenceKey", "joinSoc", "serviceId1", "serviceId2", "serviceId3", "qosControlId"
				, "beforeIncidentConsentFormUrl", "beforeManagerConsentFormUrl"}, param)) {
			throw new LogicException("VULNERABLE_VALUE", "002");
		}
		param.put("policySeq", param.getLong("policySeq"));
		param.put("clientRegAccountSeq", param.getSessionAttribute("loginAccountSeq"));
		model.addAllAttributes(service.createClient(param, clientLogo, clientAppBkgdImg, clientNameImg, incidentConsentFormImg, managerConsentFormImg, req));

		return JSON_VIEW;
	}

	@Operation(summary = "고객사 상세 조회", description = "고객사 상세 정보를 조회합니다. 개인정보 접근 이력이 기록됩니다.")
	@Parameters({
		@Parameter(name = "clientSeq", description = "고객사 시퀀스", example = "1", in = ParameterIn.PATH, schema = @Schema(type = "integer", format = "int64"))
	})
	@History(historyType = HistoryType.PERSONAL_INFO_ACCESS, reqType = "update_client")	
	@RequestMapping(value = "/{clientSeq}", method = RequestMethod.GET)
	public String createClient(
			@PathVariable("clientSeq") long clientSeq, 
			Model model, 
