	@RequestMapping(value = "/{clientSeq}", method = RequestMethod.POST, consumes = MediaType.MULTIPART_FORM_DATA_VALUE)
	public String modifyClient(
			@PathVariable("clientSeq") long clientSeq,
			@RequestParamMap(requiredValues= {"clientName","qosControlId"}) ParamMap param,
			@Parameter(name = "clientLogo", description = "고객사 로고(Web)")@RequestParam (value="clientLogo", required=false) MultipartFile clientLogo,
			@Parameter(name = "clientAppBkgdImg", description = "고객사 APP 배경 이미지")@RequestParam (value="clientAppBkgdImg", required=false) MultipartFile clientAppBkgdImg,
			@Parameter(name = "clientNameImg", description = "고객사 로고(App) 이미지")@RequestParam (value="clientNameImg", required=false) MultipartFile clientNameImg,
			@Parameter(name = "managerName", description = "담당자명", required = true, array = @ArraySchema(schema = @Schema(type = "string", example = "김서영")))@RequestParam (value="managerName") String[] managerNames,
			@Parameter(name = "managerPhone", description = "담당자 연락처", required = true, array = @ArraySchema(schema = @Schema(type = "string", example = "01025554444")))@RequestParam (value="managerPhone") String[] managerPhones,
			@Parameter(name = "beforeIncidentConsentFormUrl", description = "기존 장애대응 개인정보 활용동의 파일")@RequestParam (value="beforeIncidentConsentFormUrl", required=false) String beforeIncidentConsentFormUrl,
			@Parameter(name = "beforeManagerConsentFormUrl", description = "기존 담당자 개인정보 활용동의 파일", array = @ArraySchema(schema = @Schema(type = "string", example = "")))@RequestParam (value="beforeManagerConsentFormUrl", required=false) String[] beforeManagerConsentFormUrl,
			@Parameter(name = "incidentConsentFormImg", description = "장애대응 개인정보 활용동의 파일")@RequestParam (value="incidentConsentFormImg", required=false) MultipartFile incidentConsentFormImg,
			@Parameter(name = "managerConsentFormImg", description = "담당자 개인정보 활용동의 파일")@RequestPart (value="managerConsentFormImg", required=false) MultipartFile[] managerConsentFormImg,
			@Parameter(name = "incidentConsentFormExceptionYn", description = "장애대응 개인정보 활용동의 파일 등록 예외 여부", example = "n")@RequestParam (value="incidentConsentFormExceptionYn", required=false) String incidentConsentFormExceptionYn,
			@Parameter(name = "managerConsentFormExceptionYn", description = "담당자 개인정보 활용동의 파일 등록 예외 여부", array = @ArraySchema(schema = @Schema(type = "string", example = "n")))@RequestParam (value="managerConsentFormExceptionYn", required=false) String[] managerConsentFormExceptions,
			Model model,
			HttpServletRequest req) throws Exception {

		logger.info("[STEP 1] - Vaildation Check");
		int maxSize5MB = 1024 * 1024 * 5;
		int maxSize1MB = 1024 * 1024 * 1;
		param.put("managerNames", managerNames);
		param.put("managerPhones", managerPhones);
		param.put("managerConsentFormExceptions", managerConsentFormExceptions);

		//고객사 로고 (Web)
		if (clientLogo != null) {
			if (!CommonUtil.imgFileExtCheck(CommonUtil.getFileExt(clientLogo.getOriginalFilename()))) {
				throw new LogicException("VALIDATION_FAIL","003");
			}
			if (maxSize5MB < clientLogo.getSize()) {
				throw new LogicException("VALIDATION_FAIL","004");
			}
		}
		//고객사 로고 (APP)
		if (clientNameImg != null) {
			if (!CommonUtil.imgFileExtCheck(CommonUtil.getFileExt(clientNameImg.getOriginalFilename()))) {
				throw new LogicException("VALIDATION_FAIL","003");
			}
			if (maxSize1MB < clientNameImg.getSize()) {
				throw new LogicException("VALIDATION_FAIL","004");
			}
		}

		//고객사 APP 배경
		if (clientAppBkgdImg != null) {
			if (!CommonUtil.imgFileExtCheck(CommonUtil.getFileExt(clientAppBkgdImg.getOriginalFilename()))) {
				throw new LogicException("VALIDATION_FAIL","003");
			}
			if (maxSize1MB < clientAppBkgdImg.getSize()) {
				throw new LogicException("VALIDATION_FAIL","004");
			}
		}

		//장애대응담당자 개인정보활용동의서
		if (incidentConsentFormImg != null) {
			if (!CommonUtil.imgFileExtCheck(CommonUtil.getFileExt(incidentConsentFormImg.getOriginalFilename()))) {
				throw new LogicException("VALIDATION_FAIL","003");
			}
			if (maxSize5MB < incidentConsentFormImg.getSize()) {
				throw new LogicException("VALIDATION_FAIL","004");
			}
		} else {
			String incidentManagerName = param.getString("incidentManagerName");
			if (incidentConsentFormExceptionYn == null || "n".equals(incidentConsentFormExceptionYn)) {
				if (incidentManagerName != null && !"".equals(incidentManagerName)) {
					if (beforeIncidentConsentFormUrl == null || beforeIncidentConsentFormUrl.isEmpty()) {
						throw new LogicException("VALIDATION_FAIL", "250");
					}
				}
			}
		}

		//담당자 개인정보활용동의서
		if (managerConsentFormImg != null) {
			int index = 0;
			for (MultipartFile managerConsentFormImgInfo : managerConsentFormImg) {
				if (managerConsentFormImgInfo.isEmpty()) {
					if (managerConsentFormExceptions[index].isEmpty() || "n".equals(managerConsentFormExceptions[index])) {
						if (beforeManagerConsentFormUrl[index].isEmpty() || "".equals(beforeManagerConsentFormUrl[index])) {
							throw new LogicException("VALIDATION_FAIL", "250");
						}
					}
					index++;
					continue;
				}

				//장애대응담당자 개인정보활용동의서
				if (managerConsentFormImgInfo != null) {
					if (!CommonUtil.imgFileExtCheck(CommonUtil.getFileExt(managerConsentFormImgInfo.getOriginalFilename()))) {
						throw new LogicException("VALIDATION_FAIL","003");
					}
					if (maxSize5MB < managerConsentFormImgInfo.getSize()) {
						throw new LogicException("VALIDATION_FAIL","004");
					}
				}
				index++;
			}
		}

		if (CommonUtil.isVulnerability(new String[] {"clientName", "sqlSessionTemplate", "managerName", "smartphoneApn", "iotApn", "subTitles"
				, "knoxEnterpriseLisenceKey", "knoxLisenceKey", "joinSoc", "serviceId1", "serviceId2", "serviceId3", "qosControlId"
				, "beforeIncidentConsentFormUrl", "beforeManagerConsentFormUrl"}, param)) {
			throw new LogicException("VULNERABLE_VALUE", "002");
		}
		param.put("clientSeq", clientSeq);
		param.put("policySeq", param.getLong("policySeq"));
		param.put("beforeIncidentConsentFormUrl", beforeIncidentConsentFormUrl);
		param.put("beforeManagerConsentFormUrl", beforeManagerConsentFormUrl);
		param.put("clientUptAccountSeq", param.getSessionAttribute("loginAccountSeq"));
		model.addAllAttributes(service.modifyClient(param, clientLogo, clientAppBkgdImg, clientNameImg, incidentConsentFormImg, managerConsentFormImg, req)); 
		return JSON_VIEW;
	}

