23	@Component
24	public class SuperAdminLoginInterceptor implements HandlerInterceptor {
25		
26		private static final Logger logger = LoggerFactory.getLogger(SuperAdminLoginInterceptor.class);
27		
28		@Autowired
29		private LoginDAO dao;
30		
31		@Autowired
32		SessionLocaleResolver localeResolver;
33		
34		@Override
35		public boolean preHandle(HttpServletRequest req, HttpServletResponse res, Object handler) throws Exception {
36	
37			MDC.put("RID", CommonUtil.getRandomStr());
38	
39			String[] ajaxUriList = {"/ajax"};
40			boolean ajaxFlag = false;
41			for (String ajaxUri : ajaxUriList) {
42				if (req.getRequestURI().indexOf("/login") < 0 && req.getRequestURI().indexOf(ajaxUri) > 0) {
43					ajaxFlag = true;
44					break;
45				}
46			}
47			
48			HttpSession session = req.getSession();
49			if(!CommonUtil.isNull(session.getAttribute("loginAccountSeq"))) {
50				long accountSeq = ((Number) session.getAttribute("loginAccountSeq")).longValue();
51				String authz = dao.getAccountInfo(accountSeq).getString("authz");
52				String loginAuthz = (String) session.getAttribute("loginAuthz");
53				String loginId = (String) session.getAttribute("loginId");
54	
55				if (!authz.equals(loginAuthz)) {
56					session.invalidate();
57					res.sendRedirect("/web/login");
58					return false;
59				}
60	
61				if(!"GET".equals(req.getMethod())) {
62					logger.info("[LoginInterceptor] preHandle, Account: #{} {} [{}]", accountSeq, loginId, authz);
63				}
64	
65				if (!Authz.SYSTEM.equals(authz) && !Authz.SUPER.equals(authz) && !Authz.CONSULTING.equals(authz) && !Authz.GROUP.equals(authz)) {
66					session.invalidate();
67					res.sendRedirect("/web/login");
68					return false;
69				}
70				
71				String superHome = "/web/super/admin";
72				// 시스템,슈퍼 관리자 외 화이트 리스트
73				if (!Authz.SYSTEM.equals(authz) && !Authz.SUPER.equals(authz) 
74						&& !req.getRequestURI().equals(superHome)
75						&& !req.getRequestURI().equals(superHome + "/clients")
76						&& !req.getRequestURI().equals(superHome + "/clients/ajax")
77						&& !req.getRequestURI().matches(superHome + "/clients/\\d+/admin")) {
78					res.sendError(403);
79					return false;
80				}
81				
82				// 슈퍼 관리자 화이트 리스트
83				if (Authz.SUPER.equals(authz) && (
84				        !req.getRequestURI().equals(superHome) && 
85				        !req.getRequestURI().startsWith(superHome + "/clients") &&
86				        !req.getRequestURI().startsWith(superHome + "/traffic") &&
87				        !req.getRequestURI().startsWith(superHome + "/solutions") &&
88				        !req.getRequestURI().startsWith(superHome + "/client") &&
89				        !req.getRequestURI().startsWith(superHome + "/interworking")
90				        ) 
91				   ) {
92				    res.sendError(403);
93	                return false;
94				}
95				
96				// 슈퍼 관리자 블랙 리스트
97				if (Authz.SUPER.equals(authz) && (
98				        // 블랙 리스트
99				        req.getRequestURI().equals(superHome + "/clients/excel/make")
100				        )
101				   ) {
102				    res.sendError(403);
103	                return false;
104				}
105				
106				//로그인 중복 체크
107				ParamMap param = new ParamMap();
108				param.put("accountSeq", session.getAttribute("loginAccountSeq"));
109				param.put("loginToken", session.getAttribute("loginToken"));
110				if(!dao.checkLoginToken(param)) {
111					session.invalidate();
112					if(ajaxFlag) {
113						res.sendError(401);	
114					} else {
115						res.sendRedirect("/web/login?duplicateLogin=Y");
116					}
117					return false;
118					
119				}
120			} else {
121				//ajax에 대한 요청인데 세션이 만료된 경우
122				if(ajaxFlag) {
123					res.sendError(401);
124				} else {
125					res.sendRedirect("/web/login");
126				}
127				return false;
128			}
129			
130			if (!CommonUtil.isNull(session.getAttribute("expiredPw"))) {
131				boolean isExpiredPw = (boolean) session.getAttribute("expiredPw");
132				if (isExpiredPw) {
133					res.sendRedirect("/web/mypage/password");
134					return false;
135				}
136			}
137			
138			session.removeAttribute("loginClientSeq");
139			session.removeAttribute("loginClientLogoUrl");
140			session.removeAttribute(Constants.SQL_SESSION_TEMPLATE_NAME);
141			session.removeAttribute(Constants.SQL_TRANSACTION_MANAGER_NAME);
142			
143			session.setAttribute("lang", localeResolver.resolveLocale(req));
144			
145			dao.updateLoginDate(((Number) session.getAttribute("loginAccountSeq")).longValue());
146			
147			return true;
148		}
149		
150		@Override
151		public void postHandle(HttpServletRequest req, HttpServletResponse res, Object handler, ModelAndView mnv) throws Exception {
152			// BFCache 포함 브라우저 캐시 방지 - 뒤로가기 시 서버 재요청 강제
153			res.setHeader("Cache-Control", "no-store, no-cache, must-revalidate");
