public ResultMap login(ParamMap param) throws Exception {
	int logSeq = 0;
	logger.info("[STEP {}] - Login", ++ logSeq);
	ResultMap failResultMap = dao.getLoginFailInfo(param);
	if (failResultMap != null) {
		Date lastFailTime = Time.toDate(failResultMap.get("lastFailTime"));
		if (Time.compareDateTime(lastFailTime, Time.getCurrentDateTime(), 60)) {
			logger.info("[STEP {}] - Last login fail date in 60 min range", ++ logSeq);
			throw new LogicException("TOO_MANY_LOGIN_ATTEMTS", "503");
		}

	}

	ResultMap result = new ResultMap();
	String rawPw = param.getString("pw");
	logger.info("[STEP {}] - Get login info", ++ logSeq);
	ResultMap loginInfo = dao.getLoginInfo(param);
	if (loginInfo == null || !passwordEncoder.matches(rawPw, loginInfo.getString("pw"))) {
		dao.updateLoginFail(param);
		throw new LogicException("Cannot find user information", "500");
	}

	String encPhoneNumber = loginInfo.getString("phone");
	long accountSeq = loginInfo.getLong("accountSeq");
	param.put("accountSeq", accountSeq);
	logger.info("[STEP {}] - Request login sms passcode", ++ logSeq);
	requestSms(accountSeq, encPhoneNumber, SmsGubun.LOGIN);
	logger.info("[STEP {}] - Login success, reset fail count and date", ++ logSeq);
	dao.resetLoginFailInfo(param);
	result.put("errMsg",  "success");
	result.put("accountSeq", accountSeq);
	return result;
}

public void logout(HttpSession session) {
	ParamMap param = new ParamMap();
	param.put("accountSeq", session.getAttribute("loginAccountSeq"));
	param.put("loginToken", "");

	int logSeq = 0;
	logger.info("[STEP {}] - logout", ++ logSeq);
	session.invalidate();
	dao.updateLoginToken(param);
}

public ResultMap validateLoginSms(HttpSession session, ParamMap param) throws Exception {
	int logSeq = 0;
	logger.info("[STEP {}] - Validate login sms passcode", ++ logSeq);
	ResultMap resultMap = new ResultMap();

	Date reqDate = Time.getCurrentDateTime();
	String smsGubun = SmsGubun.LOGIN.toString();

	param.put("reqDate", reqDate);
	param.put("smsGubun", smsGubun);
	logger.info("[STEP {}] - Get login info", ++ logSeq);
	ResultMap loginInfo = dao.getLoginInfo(param); 
	long accountSeq = loginInfo.getLong("accountSeq");
