	protected String JSON_VIEW = "jsonView";

	protected String DOWN_VIEW = "downloadView";

	@ResponseStatus(HttpStatus.OK)
	@ResponseBody
	@ExceptionHandler(Exception.class)
	public ModelAndView exceptionHandler(HttpServletRequest request, HttpServletResponse response, Exception ex) {
		logger.debug("start URI : " + request.getRequestURI());

		String errName 	= ex.getClass().getName();
		String err 	= "000";
		String errMsg = null;
		String errLogMsg = "";

		//TODO 에러 처리
		if(ex instanceof LogicException) {
			err = ((LogicException)ex).getCode();
			errMsg = ((LogicException)ex).getMessage();
		} else if(ex instanceof RuntimeLogicException) {
			err = ((RuntimeLogicException)ex).getCode();
			errMsg = ((RuntimeLogicException)ex).getMessage();
		} else if(ex instanceof ResourceNotFoundException) {
			err = ((ResourceNotFoundException)ex).getCode();
			errMsg = ((ResourceNotFoundException)ex).getMessage();
		} else if (ex instanceof MyBatisSystemException) {
			err = "901";
			errMsg = "DB_CONNECTION_FAIL";
			String exMessage = ex.getMessage();
			if (exMessage != null && exMessage.indexOf("org.apache.ibatis.exceptions.TooManyResultsException") > -1) {
				err = "902";
				errMsg = "TOO_MANY_RESULTS";
			}
		} else {
			err = "999";
			errMsg = "unkown error";
			errLogMsg = ex.getMessage() != null ? ex.getMessage() : "No error message available";
		}

		ResultMap resultMap = new ResultMap();
		resultMap.setErr(err);
		resultMap.setErrMsg(errMsg);


		//TODO error code / msg정의 필요
		String viewName;
		if("XMLHttpRequest".equals(CommonUtil.nvl(request.getHeader("X-Requested-With")))) {
			viewName = JSON_VIEW;
		} else {
			viewName = "error/500error";
		}

		ModelAndView  model = new ModelAndView(viewName);
		model.addAllObjects(resultMap);
		logger.error("["+errName+"] ["+err+"] ["+errMsg+"] [" +errLogMsg+"]");
		logger.debug("end");
		return model;
	}

	@ExceptionHandler(ResourceNotFoundException.class)
	public ModelAndView notFoundExceptionHandler(HttpServletRequest request, HttpServletResponse response, Exception ex) {

		ResultMap resultMap = new ResultMap();
		resultMap.setErr("404");
		resultMap.setErrMsg("Page Not Found");

//		ModelAndView  model = new ModelAndView("redirect:/web/error");
		ModelAndView  model = new ModelAndView();
		model.addAllObjects(resultMap);
		model.setViewName("error/410error");

