    public ResultMap modifyClientCancel(ParamMap param) throws LogicException {
    	ResultMap result = new ResultMap();
        List<String> sqlIdList = Arrays.asList("client.deleteClientManagerByClientSeq");
        param.put("sqlIdList", sqlIdList);

        // LPS 등록 가능 가입자 수 체크 
        int currentJoinedLPSMemberCount = dao.getLPSJoinedMemberCountByClient(param);
        if (currentJoinedLPSMemberCount > 0) {
        	result.setErr("001");
            result.setErrMsg("UNABLE_TO_CLIENT_CANCEL_BECAUSE_EXIST_JOINED_MEMBER_IN_THE_LPS");
        	return result;
        }
        long clientSeq = param.getLong("clientSeq");
        HashMap<String, Object> clientInfo = new HashMap<String, Object>();
        clientInfo = dao.getClient(param.getLong("clientSeq"));
        String cancelStatus = String.valueOf(clientInfo.get("cancelStatus"));
        if (cancelStatus.equals(Constants.CLIENT_CANCEL_STATUS_JOIN) || cancelStatus.equals("")) { //고객사 가입(01) 상태 -> 해지 요청(02)
            logger.info("[STEP {1}] - Request Client Cancel");
            param.put("cancelStatus", Constants.CLIENT_CANCEL_STATUS_CANCEL_REQ);
            logger.info("[STEP {2}] - Update Client");
            dao.updateClientCancelStatus(param);
        } else if (cancelStatus.equals(Constants.CLIENT_CANCEL_STATUS_CANCEL)) { //고객사 해지상태 (06)
            logger.info("[STEP {1}] - Request Client Cancel Now");
            String sqlSessionTemplate = dao.getSqlSessionTemplate(param);
            List<ResultMap> memberList = new ArrayList<ResultMap>();
            if (!sqlSessionTemplate.equals("")) {
                param.put(Constants.SQL_SESSION_TEMPLATE_NAME, sqlSessionTemplate + "SqlSessionTemplate");
                memberList = dao.getMemberSeqList(param);
            } else {
                param.put(Constants.SQL_SESSION_TEMPLATE_NAME, Constants.SQL_SESSION_TEMPLATE_NAME);
                memberList = dao.getDefaultMemberList(param);
            }

            //멤버 삭제
            logger.info("[STEP {2}] - Client Member Data Delete");
            for (HashMap<String, Object> memberInfo : memberList) {
                long memberSeq = (long) memberInfo.get("memberSeq");
                param.put("memberSeq", memberSeq);
                if (!sqlSessionTemplate.equals("")) {
                    //고객사 DB
                    dao.deleteMemberBanSolnPkg(param);        //가입자 금지 솔루션 패키지
                    dao.deleteMemberChargeFee(param);        //가입자 청구 요금
                    dao.deleteMemberQosStatus(param);        //가입자 QOS 상태
                    dao.deleteQosBatch(param);                //QOS 배치
                    dao.deleteMemberNote(param);            //가입자 비고
                    dao.deleteMember(param);                //가입자
                } else {
                    //운영 DB
                    dao.deleteDefaultMemberBanSolnPkg(param);    //가입자 금지 솔루션 패키지
                    dao.deleteDefaultMemberChargeFee(param);    //가입자 청구 요금
                    dao.deleteDefaultMemberQosStatus(param);    //가입자 QOS 상태
                    dao.deleteDefaultQosBatch(param);            //QOS 배치
                    dao.deleteDefaultMemberNote(param);            //가입자 비고
                    dao.deleteDefaultMember(param);                //가입자
                }
            }

            // 25.10.23 가입자 트래픽 수집 정보/사용량 삭제는 batch에서 처리로 변경(예상 최대치 365만 건, 한번에 삭제시 timeout 발생. 5,000건씩 삭제토록.)

            logger.info("[STEP {3}] - Client Data Delete");

