        for (int i = 0; i < param.getInt("noteLen"); i++) {
            memberNoteSeqs.add(dao.getNextMemberNoteSeq());
        }
        try {

            ResultMap memberInfo = dao.getMember(param);
            if (memberInfo.getString("joinStatus").equals(Constants.MEMBER_JOIN_STATUS_JOIN)
                    || memberInfo.getString("joinStatus").equals(Constants.MEMBER_JOIN_STATUS_JOIN_REQ)) {
            	long memberSeq = memberInfo.getLong("memberSeq");

            	String s3Prefix = "resources/app/members/" + memberSeq + "/";
                String existingConsentFormUrl = param.getString("existingConsentFormUrl");
                String existingTestUserYn = param.getString("existingTestUserYn");

                if (!CommonUtil.isNull(existingTestUserYn)) {
	                if ("0".equals(param.get("corporationYn")) && !"Y".equals(param.get("testUserYn"))) {
	                	if (consentFormImg != null && !consentFormImg.isEmpty()) {
	                		//개인정보활용동의서 확장자 체크
	                		String consentFormFileName = CommonUtil.getRandomStr() + CommonUtil.getFileExt(consentFormImg.getOriginalFilename());
	                		s3FileService.upload(s3Prefix + consentFormFileName, consentFormImg);
	                		param.put("consentFormUrl", "/resources/app/members/" + memberSeq + "/" + consentFormFileName);
	                	} else if (existingConsentFormUrl != null && !existingConsentFormUrl.isEmpty()) {
	                		param.put("consentFormUrl", existingConsentFormUrl);
	                	} else {
	                        throw new LogicException("Personal information consent is required.", "607"); 
	                	}                	
	                } else if (existingConsentFormUrl != null && !existingConsentFormUrl.isEmpty()) {
                		param.put("consentFormUrl", existingConsentFormUrl);
	                }
                }

